#!/bin/sh
# I434: subsong N of a SID file plays a different stream than subsong 1, through `selecta-cli render --script`
# (the same entry as sid-decode). Fixture: tests/m3/fixtures/sid_subsongs.sid (3 subsongs, each a different triangle
# pitch, generated by make_sid_subsongs_fixture.py). The pitch is measured as sign changes of the 16-bit samples.
# Fails when SUBSONG does not reach the plugin (every subsong would then have the pitch of subsong 1).
# usage: sid_subsong.sh <selecta-cli> <sid-file>
set -u
cli=$1
sid=$2
field() { printf '%s\n' "$1" | tr ' ' '\n' | sed -n "s/^$2=//p" | head -1; }
fail() { echo "FAIL: $*"; exit 1; }
crossings() {
    od -An -v -t d2 -j 44 "$1" | tr -s " " "\n" | awk '$1 != "" { s = ($1 >= 0); if (n > 0 && s != p) c++; p = s; n++ } END { printf "%d", c }'
}
render_sub() {
    rm -f "ss_$1.wav"
    printf 'SUBSONG %s\n' "$1" > "ss_$1.script"
    out=$("$cli" render "$sid" --script "ss_$1.script" --output "ss_$1.wav" --seconds 2 --rate 44100 2>/dev/null) ||
        fail "render subsong $1 failed"
    [ "$(field "$out" replayer)" = "sid" ] || fail "replayer=$(field "$out" replayer), want sid"
    crossings "ss_$1.wav"
}
c0=$(render_sub 0)
c1=$(render_sub 1)
c2=$(render_sub 2)
[ "$c0" -gt 100 ] || fail "subsong 1 silent or too low (crossings $c0)"
[ "$c1" -gt "$c0" ] || fail "subsong 2 not higher than subsong 1 ($c1 vs $c0)"
[ "$c2" -gt "$c1" ] || fail "subsong 3 not higher than subsong 2 ($c2 vs $c1)"
echo "sid_subsong_ok $c0 $c1 $c2"
